import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build lookup of current target state per order_id
    target_dict = {}
    for row in target_state.itertuples(index=False):
        target_dict[row.order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    # Deduplicate CDC events by seq (at-least-once delivery -> apply once)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Sort globally by seq (the only trustworthy ordering)
    cdc_events = cdc_events.sort_values("seq", kind="mergesort")

    tombstone_rows = []

    processed_orders = set()

    final_states = {}  # order_id -> dict(status, amount, last_seq) or None if deleted
    # initialize with existing target rows (will be overwritten if events processed)
    for oid, info in target_dict.items():
        final_states[oid] = dict(info)

    for order_id, group in cdc_events.groupby("order_id", sort=False):
        processed_orders.add(order_id)

        existing = target_dict.get(order_id)
        if existing is not None:
            orig_last_seq = existing["last_seq"]
            # Replay guard: skip events with seq <= existing last_seq
            group = group[group["seq"] > orig_last_seq]
            if group.empty:
                # nothing changes for this order
                continue
            state = (existing["status"], existing["amount"])
            had_row_ever = True
        else:
            state = None
            had_row_ever = False

        last_eff_seq = existing["last_seq"] if existing is not None else None
        last_eff_op = None

        for ev in group.itertuples(index=False):
            op = ev.op
            seq = ev.seq
            if op in ("I", "U"):
                if state is None:
                    # create from scratch, amount as-is (NULL stays NULL)
                    new_status = ev.status
                    new_amount = ev.amount
                else:
                    new_status = ev.status
                    if op == "U" and pd.isna(ev.amount):
                        new_amount = state[1]
                    else:
                        new_amount = ev.amount
                state = (new_status, new_amount)
                had_row_ever = True
                last_eff_op = op
                last_eff_seq = seq
            elif op == "D":
                if state is not None:
                    state = None
                    last_eff_op = "D"
                    last_eff_seq = seq
                # else: D on a missing order does nothing, not tracked

        if state is None:
            # order ends up deleted
            final_states[order_id] = None
            if had_row_ever and last_eff_op == "D":
                tombstone_rows.append(
                    {"order_id": order_id, "deleted_seq": last_eff_seq}
                )
        else:
            final_states[order_id] = {
                "status": state[0],
                "amount": state[1],
                "last_seq": last_eff_seq,
            }

    # Build new_state rows
    new_state_rows = []
    for oid, info in final_states.items():
        if info is None:
            continue
        new_state_rows.append(
            {
                "order_id": oid,
                "status": info["status"],
                "amount": info["amount"],
                "last_seq": info["last_seq"],
            }
        )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    # Ensure proper dtypes where possible
    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype(
            target_state["order_id"].dtype
            if not target_state.empty
            else cdc_events["order_id"].dtype
        )
        new_state["last_seq"] = new_state["last_seq"].astype(
            target_state["last_seq"].dtype
            if not target_state.empty
            else cdc_events["seq"].dtype
        )

    if not tombstones.empty:
        tombstones["order_id"] = tombstones["order_id"].astype(
            target_state["order_id"].dtype
            if not target_state.empty
            else cdc_events["order_id"].dtype
        )
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype(
            cdc_events["seq"].dtype
        )

    return {"new_state": new_state, "tombstones": tombstones}
